'use strict';

var discreteUniform = require( '@stdlib/random/base/discrete-uniform' );
var srotmg = require( './../lib' );

var out;
var i;
var d1;
var d2;
var x1;
var y1;
for ( i = 0; i < 100; i++ ) {
	d1 = discreteUniform( -5, 5 );
	d2 = discreteUniform( -5, 5 );
	x1 = discreteUniform( -5, 5 );
	y1 = discreteUniform( -5, 5 );
	out = srotmg( d1, d2, x1, y1 );
	console.log( out );
}
